#!/run/current-system/sw/bin/python3
import http.client
import os
import signal
import sqlite3
import sys
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote_to_bytes, urlsplit

DB_PATH = "/var/lib/blueprint/blueprint.db"
API_HOST = "127.0.0.1"
API_PORT = 18081
EDGE_HOST = "0.0.0.0"
EDGE_PORT = 8080


def database():
    connection = sqlite3.connect(DB_PATH, timeout=30.0)
    connection.execute("PRAGMA busy_timeout=30000")
    connection.execute("PRAGMA synchronous=FULL")
    return connection


def initialize_database():
    os.makedirs(os.path.dirname(DB_PATH), mode=0o755, exist_ok=True)
    connection = database()
    try:
        connection.execute("PRAGMA journal_mode=WAL")
        connection.execute(
            """CREATE TABLE IF NOT EXISTS jobs (
                id BLOB PRIMARY KEY,
                payload BLOB NOT NULL,
                state TEXT NOT NULL,
                result BLOB,
                created_at REAL NOT NULL
            )"""
        )
        connection.execute(
            "CREATE INDEX IF NOT EXISTS jobs_state_created ON jobs(state, created_at)"
        )
        connection.commit()
    finally:
        connection.close()


def job_id(handler):
    path = urlsplit(handler.path).path
    prefix = "/jobs/"
    if not path.startswith(prefix):
        return None
    encoded = path[len(prefix):]
    if not encoded:
        return None
    try:
        value = unquote_to_bytes(encoded)
    except ValueError:
        return None
    return value or None


def request_body(handler):
    value = handler.headers.get("Content-Length")
    if value is None:
        return None
    try:
        length = int(value)
    except ValueError:
        return None
    if length < 0:
        return None
    return handler.rfile.read(length)


def send_bytes(handler, status, body, content_type="text/plain; charset=utf-8"):
    handler.send_response(status)
    handler.send_header("Content-Type", content_type)
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Connection", "close")
    handler.end_headers()
    if body:
        handler.wfile.write(body)


class APIHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        sys.stderr.write("api: " + (fmt % args) + "\n")

    def do_GET(self):
        path = urlsplit(self.path).path
        if path == "/health":
            send_bytes(self, 200, b"ready")
            return
        identifier = job_id(self)
        if identifier is None:
            send_bytes(self, 404, b"not found")
            return
        connection = database()
        try:
            row = connection.execute(
                "SELECT state, result FROM jobs WHERE id = ?", (identifier,)
            ).fetchone()
        finally:
            connection.close()
        if row is None:
            send_bytes(self, 404, b"not found")
        elif row[0] == "completed":
            send_bytes(self, 200, row[1] or b"", "application/octet-stream")
        else:
            send_bytes(self, 409, b"pending")

    def do_PUT(self):
        identifier = job_id(self)
        if identifier is None:
            send_bytes(self, 404, b"not found")
            return
        body = request_body(self)
        if body is None:
            send_bytes(self, 411, b"length required")
            return
        connection = database()
        try:
            connection.execute(
                "INSERT OR IGNORE INTO jobs(id, payload, state, result, created_at) "
                "VALUES(?, ?, 'queued', NULL, ?)",
                (identifier, body, time.time()),
            )
            connection.commit()
        finally:
            connection.close()
        send_bytes(self, 202, b"accepted")

    def do_HEAD(self):
        path = urlsplit(self.path).path
        if path == "/health":
            self.send_response(200)
            self.send_header("Content-Length", "5")
            self.end_headers()
        else:
            self.send_response(404)
            self.send_header("Content-Length", "9")
            self.end_headers()


class EdgeHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        sys.stderr.write("edge: " + (fmt % args) + "\n")

    def _proxy(self):
        body = None
        if self.command == "PUT":
            body = request_body(self)
            if body is None:
                send_bytes(self, 411, b"length required")
                return
        target = self.path
        connection = http.client.HTTPConnection(API_HOST, API_PORT, timeout=30)
        try:
            headers = {}
            if body is not None:
                headers["Content-Length"] = str(len(body))
                content_type = self.headers.get("Content-Type")
                if content_type:
                    headers["Content-Type"] = content_type
            connection.request(self.command, target, body=body, headers=headers)
            response = connection.getresponse()
            response_body = response.read()
            content_type = response.getheader("Content-Type")
            send_bytes(
                self,
                response.status,
                response_body,
                content_type or "text/plain; charset=utf-8",
            )
        except (OSError, http.client.HTTPException):
            send_bytes(self, 503, b"unavailable")
        finally:
            connection.close()

    def do_GET(self):
        self._proxy()

    def do_PUT(self):
        self._proxy()

    def do_HEAD(self):
        self._proxy()


def serve(handler, host, port):
    server = ThreadingHTTPServer((host, port), handler)
    server.daemon_threads = True
    server.serve_forever(poll_interval=0.2)


def worker_loop():
    initialize_database()
    connection = database()
    try:
        connection.execute("UPDATE jobs SET state='queued' WHERE state='processing'")
        connection.commit()
    finally:
        connection.close()

    while True:
        connection = database()
        claimed = None
        try:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute(
                "SELECT id, payload FROM jobs WHERE state='queued' "
                "ORDER BY created_at, rowid LIMIT 1"
            ).fetchone()
            if row is not None:
                connection.execute(
                    "UPDATE jobs SET state='processing' WHERE id=? AND state='queued'",
                    (row[0],),
                )
                connection.commit()
                claimed = row
            else:
                connection.rollback()
        finally:
            connection.close()

        if claimed is None:
            time.sleep(0.1)
            continue

        identifier, payload = claimed
        connection = database()
        try:
            connection.execute(
                "UPDATE jobs SET state='completed', result=? WHERE id=? "
                "AND state='processing'",
                (payload, identifier),
            )
            connection.commit()
        finally:
            connection.close()


def main(role):
    initialize_database()
    if role == "edge":
        serve(EdgeHandler, EDGE_HOST, EDGE_PORT)
    elif role == "api":
        serve(APIHandler, API_HOST, API_PORT)
    elif role == "worker":
        worker_loop()
    else:
        raise SystemExit("unknown role")

